def isValid(s):
    stack = []
    pairs = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in pairs:
            # closing bracket
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()
        else:
            # opening bracket
            stack.append(char)

    return len(stack) == 0

