def longest_valid_parentheses(s):
    max_len = 0
    stack = [-1]

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_len = max(max_len, i - stack[-1])

    return max_len

def nextGreaterElement(nums):
    result = [-1] * len(nums)
    stack = []  # stores indexes

    for i in range(len(nums)):
        # Pop all indexes whose answer is nums[i]
        while stack and nums[i] > nums[stack[-1]]:
            index = stack.pop()
            result[index] = nums[i]
        stack.append(i)

    return result

def dailyTemperatures(temps):
    result = [0] * len(temps)
    stack = []  # indices

    for i in range(len(temps)):
        # Pop all colder days
        while stack and temps[i] > temps[stack[-1]]:
            idx = stack.pop()
            result[idx] = i - idx

        stack.append(i)

    return result

