def k_largest(nums, k):
    heap = nums[:k]
    heapq.heapify(heap)  # O(k)
    for num in nums[k:]:
        if num > heap[0]:  # beat the Kth largest?
            heapq.heapreplace(heap, num)
    return heap  # O(n log k)

