        # Visited neighbor that's not parent = cycle
        if visited[neighbor] and neighbor != parent:
            return True
        # Recurse on unvisited
        if not visited[neighbor]:
            if hasCycle(adj_list, neighbor, visited, node):
                return True
    return False

