def flood_fill(image, sr, sc, color):
    rows, cols = len(image), len(image[0])
    orig = image[sr][sc]
    if orig == color:
        return image

    def dfs(r, c):
        if image[r][c] == orig:
            image[r][c] = color
            if r >= 1: dfs(r - 1, c)
            if r + 1 < rows: dfs(r + 1, c)
            if c >= 1: dfs(r, c - 1)
            if c + 1 < cols: dfs(r, c + 1)

    dfs(sr, sc)
    return image

